        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        sleep(3)
        print("STATE \(app.state.rawValue)")
        let all = app.descendants(matching: .any)
        print("COUNT \(all.count)")
        for (i, e) in all.allElementsBoundByIndex.enumerated() {
            print("E\(i) type=\(e.elementType.rawValue) label=\(e.label) id=\(e.identifier) frame=\(NSStringFromCGRect(e.frame))")
        }
    }
}

